    R, C = len(grid), len(grid[0])
    comp = [[-1]*C for _ in range(R)]
    size = []
    for i in range(R):
        for j in range(C):
            if comp[i][j] == -1:
                cid = len(size)
                col = grid[i][j]
                q = deque([(i, j)])
                comp[i][j] = cid
                n = 0
                while q:
                    x, y = q.popleft()
                    n += 1
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a, b = x+dx, y+dy
                        if 0 <= a < R and 0 <= b < C and comp[a][b] == -1 and grid[a][b] == col:
                            comp[a][b] = cid
                            q.append((a, b))
                size.append(n)
    keep = [cid for cid in range(len(size)) if size[cid] >= 3]
    out = [row[:] for row in grid]
    q = deque()
    for i in range(R):
        for j in range(C):
            if comp[i][j] in keep:
                q.append((i, j))
    seen = [[False]*C for _ in range(R)]
    for i, j in q:
        seen[i][j] = True
    while q:
        x, y = q.popleft()
        for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
            a, b = x+dx, y+dy
            if 0 <= a < R and 0 <= b < C and not seen[a][b]:
                seen[a][b] = True
                out[a][b] = out[x][y]
                q.append((a, b))
    return out
