from collections import Counter, deque

def transform(grid):
    R, C = len(grid), len(grid[0])
    comp = [[-1] * C for _ in range(R)]
    size = []
    for i in range(R):
        for j in range(C):
            if comp[i][j] == -1:
                cid = len(size)
                col = grid[i][j]
                q = deque([(i, j)])
                comp[i][j] = cid
                n = 0
                while q:
                    x, y = q.popleft()
                    n += 1
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        a, b = x + dx, y + dy
                        if 0 <= a < R and 0 <= b < C and comp[a][b] == -1 and grid[a][b] == col:
                            comp[a][b] = cid
                            q.append((a, b))
                size.append(n)
    out = [row[:] for row in grid]
    for i in range(R):
        for j in range(C):
            if size[comp[i][j]] < 3:
                cnt = Counter()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = i + dx, j + dy
                    if 0 <= a < R and 0 <= b < C:
                        cnt[grid[a][b]] += 1
                if cnt:
                    out[i][j] = cnt.most_common(1)[0][0]
    return out
